import { Box, Typography, Grid } from '@mui/material';
import VideoPreview from './VideoPreview';
import ImagePreview from './ImagePreview';
import RemoveImageButton from './RemoveImageButton';
import PreviewCheckmark from './PreviewCheckmark';
import ImageFilename from './ImageFilename';

const UserImagesGrid = ({ mediaItems = [], currentPreviewIndex, setPreviewByIndex, handleRemoveMediaItem }) => (
    <Box sx={{ p: 2 }}>
        <Typography variant="subtitle1" gutterBottom>
            Total media ({mediaItems.length})
        </Typography>
        <Grid container spacing={1}>
            {mediaItems.map((media, index) => (
                <Grid item key={media.id} xs={6} sm={4} md={3}>
                    <Box position="relative" sx={{ cursor: 'pointer' }} onClick={() => setPreviewByIndex(index)}>
                        {media.type === 'video' ? <VideoPreview media={media} /> : <ImagePreview media={media} />}
                        {currentPreviewIndex === index && <PreviewCheckmark />}
                        <RemoveImageButton
                            onClick={(e) => {
                                e.stopPropagation();
                                handleRemoveMediaItem(index);
                            }}
                        />
                    </Box>
                    <ImageFilename filename={media.filename || media.source || `Media ${index + 1}`} />
                </Grid>
            ))}
        </Grid>
    </Box>
);

export default UserImagesGrid;
