// SocialPreview.jsx
import { Box, Paper, Typography, Avatar, Button } from '@mui/material';
import { Favorite, ChatBubbleOutline, Share, MoreHoriz } from '@mui/icons-material';
import defaultImage from '../../../assets/images/landing/default.jpg';

const platformIcons = {
    facebook: {
        like: <Favorite fontSize="small" sx={{ color: 'primary.dark' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'primary.dark' }} />,
        share: <Share fontSize="small" sx={{ color: 'primary.dark' }} />
    },
    instagram: {
        like: <Favorite fontSize="small" sx={{ color: 'error.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'text.primary' }} />,
        share: <Share fontSize="small" sx={{ color: 'text.primary' }} />
    },
    twitter: {
        like: <Favorite fontSize="small" sx={{ color: 'info.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'info.main' }} />,
        share: <Share fontSize="small" sx={{ color: 'info.main' }} />
    },
    linkedin: {
        like: <Favorite fontSize="small" sx={{ color: 'info.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'info.main' }} />,
        share: <Share fontSize="small" sx={{ color: 'info.main' }} />
    },
    youtube: {
        like: <Favorite fontSize="small" sx={{ color: 'error.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'text.primary' }} />,
        share: <Share fontSize="small" sx={{ color: 'text.primary' }} />
    },
    tiktok: {
        like: <Favorite fontSize="small" sx={{ color: 'secondary.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'text.primary' }} />,
        share: <Share fontSize="small" sx={{ color: 'text.primary' }} />
    },
    pinterest: {
        like: <Favorite fontSize="small" sx={{ color: 'error.main' }} />,
        comment: <ChatBubbleOutline fontSize="small" sx={{ color: 'text.primary' }} />,
        share: <Share fontSize="small" sx={{ color: 'text.primary' }} />
    }
};

const actionLabels = {
    facebook: { like: 'Like', comment: 'Comment', share: 'Share' },
    instagram: { like: 'Like', comment: 'Comment', share: 'Share' },
    twitter: { like: 'Like', comment: 'Reply', share: 'Retweet' },
    linkedin: { like: 'Like', comment: 'Comment', share: 'Share' },
    youtube: { like: 'Like', comment: 'Comment', share: 'Share' },
    tiktok: { like: 'Like', comment: 'Comment', share: 'Share' },
    pinterest: { like: 'Save', comment: 'Comment', share: 'Send' }
};

const SocialPreview = ({ platform, caption, mediaItem, maxWidth = 360, showHeader = true }) => {
    // Get media URL - supports both local files and external sources
    const mediaUrl = mediaItem?.url || mediaItem?.urls?.thumb;

    return (
        <Box sx={{ mb: 3, scrollMarginTop: '16px', backgroundColor: 'white' }}>
            <Paper
                sx={{
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: platform === 'instagram' ? 0 : 1,
                    backgroundColor: 'white',
                    boxShadow: 5,
                    overflow: 'hidden',
                    maxWidth,
                    mx: 'auto'
                }}
            >
                {showHeader && (
                    <Box sx={{ p: 1.5, borderBottom: '1px solid', borderColor: 'divider' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Avatar src="https://storage.googleapis.com/a1aa/image/0f4d252b-efce-49e4-0f41-61b0c97cac30.jpg" />
                            <Typography color="primary.dark" fontWeight="bold">
                                {platform.charAt(0).toUpperCase() + platform.slice(1)} Page
                            </Typography>
                            {platform === 'twitter' && (
                                <Box sx={{ ml: 'auto' }}>
                                    <MoreHoriz fontSize="small" />
                                </Box>
                            )}
                        </Box>
                    </Box>
                )}

                <Box sx={{ p: platform === 'instagram' ? 0 : 1.5 }}>
                    {caption && (
                        <Typography
                            sx={{
                                mb: 1,
                                fontSize: platform === 'twitter' ? '0.9rem' : '0.9rem',
                                fontFamily: platform === 'twitter' ? '"Segoe UI", Roboto, sans-serif' : 'inherit'
                            }}
                        >
                            {caption}
                        </Typography>
                    )}

                    {mediaUrl ? (
                        <Box
                            component="img"
                            src={mediaUrl}
                            sx={{
                                width: '100%',
                                borderRadius: platform === 'instagram' ? 0 : 1,
                                maxHeight: 300,
                                objectFit: 'cover'
                            }}
                            alt="Post media"
                        />
                    ) : (
                        <Box
                            component="img"
                            src={defaultImage}
                            sx={{
                                width: '100%',
                                borderRadius: platform === 'instagram' ? 0 : 1,
                                maxHeight: 300,
                                objectFit: 'cover',
                                backgroundColor: '#f5f5f5'
                            }}
                            alt="Default media"
                        />
                    )}
                </Box>

                <Box
                    sx={{
                        p: 1,
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        backgroundColor: platform === 'twitter' ? '#f7f9fa' : '#f7f9fa'
                    }}
                >
                    <Typography variant="caption" color="text.secondary">
                        5 mins ago
                    </Typography>
                    <Box
                        sx={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            mt: 1,
                            '& .MuiButton-root': {
                                minWidth: 'auto',
                                color: 'text.secondary'
                            }
                        }}
                    >
                        <Button size="small" startIcon={platformIcons[platform]?.like}>
                            {actionLabels[platform]?.like}
                        </Button>
                        <Button size="small" startIcon={platformIcons[platform]?.comment}>
                            {actionLabels[platform]?.comment}
                        </Button>
                        <Button size="small" startIcon={platformIcons[platform]?.share}>
                            {actionLabels[platform]?.share}
                        </Button>
                    </Box>
                </Box>
            </Paper>
        </Box>
    );
};

SocialPreview.defaultProps = {
    caption: '',
    mediaItem: null,
    maxWidth: 360,
    showHeader: true
};

export default SocialPreview;
