// ImagePreview.jsx
import { Box } from '@mui/material';

const ImagePreview = ({ media }) => (
    <Box
        component="img"
        src={media.url || media.urls?.thumb}
        alt={media.filename || media.alt_description || 'Preview'}
        sx={{
            width: '100%',
            height: 100,
            objectFit: 'cover',
            borderRadius: 1,
            border: '1px solid #ddd'
        }}
    />
);

export default ImagePreview;
