import React from 'react';
import { Button } from '@mui/material';
import { useTheme } from '@mui/material/styles';

const TabButton = ({ activeTab, tabName, onClick, startIcon, children }) => {
    const theme = useTheme();

    return (
        <Button
            variant={activeTab === tabName ? 'contained' : 'outlined'}
            onClick={() => onClick(tabName)}
            startIcon={startIcon}
            sx={{
                textTransform: 'none',
                backgroundColor: activeTab === tabName ? theme.palette.primary.dark : theme.palette.primary.main,
                color: activeTab === tabName ? 'white' : 'text.primary',
                borderColor: activeTab === tabName ? 'primary.main' : 'divider',
                '&:hover': {
                    backgroundColor: activeTab === tabName ? theme.palette.primary.dark : theme.palette.primary.main,
                    borderColor: activeTab === tabName ? 'primary.dark' : 'grey.400'
                }
            }}
        >
            {children}
        </Button>
    );
};

export default TabButton;
